                        </article>
                      `
                    )
                    .join("")}
                </div>
              </div>
            </div>
          </section>
        `;
      }

      function Editorial() {
        return `
          <section class="section" id="editorial" aria-labelledby="editorial-heading">
            <div class="shell">
              <div class="section__header">
                <div>
                  <p class="eyebrow">Editorial</p>
                  <h2 id="editorial-heading">Stories that help products feel more personal.</h2>
