  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const featuredProducts = [
        {
          id: "forme-knit-runner",
          category: "New arrival",
          name: "Forme Knit Runner",
          price: "$128",
          rating: "4.8",
          description: "A lightweight everyday sneaker with soft cushioning and a refined, minimal profile.",
          tone: "#2d6f7a",
        },
        {
          id: "lane-tote-24l",
          category: "Editor pick",
          name: "Lane Tote 24L",
          price: "$92",
          rating: "4.9",
          description: "Structured carryall with a durable finish, interior organizers, and magnetic closure.",
          tone: "#c46a2b",
        },
        {
          id: "cloudloop-coat",
          category: "Best seller",
          name: "Cloudloop Coat",
          price: "$188",
          rating: "4.7",
          description: "Soft-touch outer layer designed for layered city dressing and shifting weather.",
          tone: "#7c6a55",
        },
        {
          id: "arc-table-lamp",
          category: "Limited drop",
          name: "Arc Table Lamp",
          price: "$74",
          rating: "4.9",
          description: "Warm ambient light in a compact silhouette that works on desks and side tables.",
          tone: "#577b63",
        },
      ];

      const dealItems = [
        {
          title: "Bundle and save on home refresh essentials",
          body: "Up to 30% off curated sets for the living room, entryway, and bedroom.",
          cta: "Shop bundles",
        },
        {
          title: "Members get early access every Thursday",
          body: "Sign in to unlock new colors, restocks, and limited runs before the public launch.",
          cta: "Join membership",
        },
      ];

      const editorialStories = [
        {
          id: "modern-capsule-wardrobe",
          title: "How to build a modern capsule wardrobe",
          deck: "A practical guide to versatile pieces that work across commutes, weekends, and travel.",
          tone: "#1f6f78",
        },
        {
          id: "spring-collection-notes",
          title: "Design notes from our spring collection",
          deck: "Textures, palettes, and silhouettes shaped by easy movement and long-lasting materials.",
          tone: "#c46a2b",
        },
        {
          id: "small-upgrades-big-impact",
          title: "The retail ritual: small upgrades with big impact",
          deck: "Three simple ways to make everyday routines feel more considered without adding clutter.",
          tone: "#6b5a4a",
        },
      ];

      const formatStars = (value) => `${value} / 5`;

      function Header() {
        return `
          <header class="site-header">
            <div class="shell site-header__inner">
              <a class="brand" href="#main-content" aria-label="Northstar Market home">
                <span class="brand__mark" aria-hidden="true">N</span>
                <span>Northstar Market</span>
              </a>
              <nav class="site-nav" aria-label="Primary">
                <ul>
                  <li><a href="#featured">Featured</a></li>
                  <li><a href="#deals">Deals</a></li>
                  <li><a href="#editorial">Editorial</a></li>
                </ul>
              </nav>
            </div>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="hero">
            <div class="shell hero__panel">
              <div>
                <p class="eyebrow">Retail, refreshed</p>
                <h1>Better essentials for the way people shop now.</h1>
                <p class="lede">
                  Discover an elevated mix of new-season products, limited-time offers, and
                  editorial guidance designed to help customers browse quickly and buy with confidence.
                </p>
                <div class="hero__actions">
                  <a class="button button--primary" href="#featured">Shop featured products</a>
                  <a class="button button--secondary" href="#editorial">Read the stories</a>
                </div>
                <div class="hero__stats" aria-label="Store highlights">
                  <div class="stat">
                    <strong>120+</strong>
                    <span>curated products</span>
                  </div>
                  <div class="stat">
                    <strong>48 hr</strong>
                    <span>express delivery window</span>
                  </div>
                  <div class="stat">
                    <strong>4.8/5</strong>
                    <span>average customer rating</span>
                  </div>
                </div>
              </div>
              <div class="hero__visual" aria-hidden="true">
                <div class="feature-card">
                  <div class="feature-card__art">
                    <div class="product-mockup"></div>
                  </div>
                </div>
              </div>
            </div>
          </section>
        `;
      }

      function ProductCard(product) {
        return `
          <article class="product-card" id="${product.id}" style="--tone: ${product.tone}">
            <div class="product-card__media" aria-hidden="true">
              <div class="product-card__swatch"></div>
            </div>
            <div class="product-card__body">
              <div class="meta-row">
                <span class="badge">${product.category}</span>
                <span aria-label="Rating ${formatStars(product.rating)}">★ ${product.rating}</span>
              </div>
              <h3>${product.name}</h3>
              <p>${product.description}</p>
              <div class="product-card__footer">
                <span class="price">${product.price}</span>
                <a class="text-link" href="#${product.id}" aria-label="View details for ${product.name}">
                  View product
                </a>
              </div>
            </div>
          </article>
        `;
      }

      function FeaturedProducts() {
        return `
          <section class="section" id="featured" aria-labelledby="featured-heading">
            <div class="shell">
              <div class="section__header">
                <div>
                  <p class="eyebrow">Featured products</p>
                  <h2 id="featured-heading">Customer favorites, styled for everyday life.</h2>
                </div>
                <p>
                  A balanced selection of apparel, accessories, and home goods with quick scan details
                  and strong visual hierarchy.
                </p>
              </div>
              <div class="grid grid--products">
                ${featuredProducts.map(ProductCard).join("")}
              </div>
            </div>
          </section>
        `;
      }

      function Deals() {
        return `
          <section class="section" id="deals" aria-labelledby="deals-heading">
            <div class="shell">
              <div class="section__header">
                <div>
                  <p class="eyebrow">Deals</p>
                  <h2 id="deals-heading">Limited-time offers built to convert quickly.</h2>
                </div>
                <p>
                  Highlighted promotions are clear, scannable, and easy to act on across desktop and mobile.
                </p>
              </div>
              <div class="grid grid--deals">
                <article class="deal-card deal-card--spotlight">
                  <div class="deal-card__body">
                    <span class="badge">Today only</span>
                    <h3 style="font-size: clamp(1.7rem, 3vw, 2.4rem); margin-top: 0.8rem;">
                      Save 20% on selected wardrobe staples
                    </h3>
                    <p>
                      Build a sharper lineup with outerwear, knitwear, and accessories marked down for a
                      short window.
                    </p>
                    <p><strong>Use code:</strong> REFRESH20</p>
                    <a class="button button--primary" href="#featured">Browse the sale</a>
                  </div>
                </article>
                <div class="deal-panel">
                  ${dealItems
                    .map(
                      (item) => `
                        <article class="deal-grid__item">
                          <span class="badge">Promotion</span>
                          <h3>${item.title}</h3>
                          <p>${item.body}</p>
                          <a class="text-link" href="#featured">${item.cta}</a>
                        </article>
                      `
                    )
                    .join("")}
                </div>
              </div>
            </div>
          </section>
        `;
      }

      function Editorial() {
        return `
          <section class="section" id="editorial" aria-labelledby="editorial-heading">
            <div class="shell">
              <div class="section__header">
                <div>
                  <p class="eyebrow">Editorial</p>
                  <h2 id="editorial-heading">Stories that help products feel more personal.</h2>
                </div>
                <p>
                  Short-form content supports discovery, reduces friction, and gives the home page a more
                  magazine-like feel.
                </p>
              </div>
              <div class="grid grid--stories">
                ${editorialStories
                  .map(
                    (story) => `
                      <article class="story-card" id="${story.id}" style="--tone: ${story.tone}">
                        <div class="story-card__image" aria-hidden="true">
                          <span class="story-card__line"></span>
                        </div>
                        <div class="story-card__body">
                          <span class="badge">In focus</span>
                          <h3>${story.title}</h3>
                          <p>${story.deck}</p>
                          <a class="text-link" href="#${story.id}" aria-label="Read more about ${story.title}">
                            Read more
                          </a>
                        </div>
                      </article>
                    `
                  )
                  .join("")}
              </div>
            </div>
          </section>
        `;
      }

      function Footer() {
        return `
          <footer class="footer">
            <div class="shell footer__inner">
              <p>&copy; 2026 Northstar Market. Modern retail, made simple.</p>
              <p><a href="#main-content">Back to top</a></p>
            </div>
          </footer>
        `;
      }

      function App() {
        return `
          ${Header()}
          <main id="main-content">
            ${Hero()}
            ${FeaturedProducts()}
            ${Deals()}
            ${Editorial()}
          </main>
          ${Footer()}
        `;
      }

      document.getElementById("root").innerHTML = App();
    </script>
  </body>
</html>
